-- Database: fashionhub (PostgreSQL 14+)
-- Padanan 1:1 dari database/schema.sql (versi MySQL).
--
-- Perbedaan yang disengaja:
--  * Id tetap INT AUTO_INCREMENT di MySQL -> GENERATED BY DEFAULT AS IDENTITY di sini,
--    supaya migrasi data lama bisa mempertahankan id aslinya.
--  * Kolom timestamp memakai TIMESTAMP (tanpa zona waktu) yang berisi UTC, bukan
--    TIMESTAMPTZ. Alasannya: server MySQL mengirim jam UTC apa adanya, jadi data lama
--    harus tersimpan dengan angka yang sama persis. src/config/db.js membaca kolom ini
--    sebagai UTC agar JSON-nya identik dengan respons sebelumnya.
--  * ON UPDATE CURRENT_TIMESTAMP di MySQL tidak ada di Postgres -> trigger set_updated_at.
--  * InnoDB + ON DELETE RESTRICT/SET NULL sudah jadi perilaku bawaan FOREIGN KEY.

CREATE TABLE IF NOT EXISTS roles (
  id   INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(20) NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS users (
  id            INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name          VARCHAR(100) NOT NULL,
  email         VARCHAR(150) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  role_id       INT NOT NULL REFERENCES roles(id),
  created_at    TIMESTAMP NOT NULL DEFAULT (now() AT TIME ZONE 'utc')
);

CREATE TABLE IF NOT EXISTS categories (
  id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        VARCHAR(100) NOT NULL UNIQUE,
  description VARCHAR(255) NULL,
  created_at  TIMESTAMP NOT NULL DEFAULT (now() AT TIME ZONE 'utc')
);

CREATE TABLE IF NOT EXISTS products (
  id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  category_id INT NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,
  created_by  INT NULL REFERENCES users(id) ON DELETE SET NULL,
  name        VARCHAR(150) NOT NULL,
  description TEXT NULL,
  price       NUMERIC(12,2) NOT NULL,
  stock       INT NOT NULL DEFAULT 0,
  image_url       VARCHAR(500) NULL,   -- secure_url dari Cloudinary
  image_public_id VARCHAR(255) NULL,   -- public_id Cloudinary (untuk hapus/ganti gambar)
  created_at  TIMESTAMP NOT NULL DEFAULT (now() AT TIME ZONE 'utc'),
  updated_at  TIMESTAMP NOT NULL DEFAULT (now() AT TIME ZONE 'utc')
);

CREATE INDEX IF NOT EXISTS idx_products_name ON products (name);
CREATE INDEX IF NOT EXISTS idx_products_category ON products (category_id);
CREATE INDEX IF NOT EXISTS idx_products_created_by ON products (created_by);

-- Padanan ON UPDATE CURRENT_TIMESTAMP MySQL.
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at := (now() AT TIME ZONE 'utc');
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_products_updated_at ON products;
CREATE TRIGGER trg_products_updated_at
  BEFORE UPDATE ON products
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

INSERT INTO roles (name) VALUES ('admin'), ('user')
ON CONFLICT (name) DO NOTHING;

-- Akun admin & data contoh dibuat lewat: npm run seed
